claim.text:
(fun (s : ℕ) =>
    if j < s + (j + (1 : ℕ)) then q j * a (s + (j + (1 : ℕ)) - j - (1 : ℕ)) * x ^ (s + (j + (1 : ℕ))) else (0 : ℝ)) =
  fun (s : ℕ) => q j * x ^ j * (a s * x ^ (s + (1 : ℕ)))

